const std = @import("std"); const pdf_extractor = @import("pdf_extractor.zig"); pub fn main() !void { var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator); defer arena.deinit(); const alloc = arena.allocator(); pdf_extractor.initPdfEngine(); defer pdf_extractor.destroyPdfEngine(); const args = try std.process.argsAlloc(alloc); if (args.len < 3) { std.debug.print("Usage: zig_extractor <pdf_path> <out_dir> [target_page]\n", .{}); return; } const pdf_path = args[1]; const out_dir = args[2]; var target_page: ?i32 = 2; if (args.len >= 4) { target_page = std.fmt.parseInt(i32, args[3], 10) catch 2; } std.debug.print("Running Native Zig Extractor on: {s} -> Output: {s} (Page {?d})\n", .{ pdf_path, out_dir, target_page }); const res = try pdf_extractor.extractPdfPackage(alloc, pdf_path, 700, target_page, out_dir); std.debug.print("SUCCESS! Output JSON: {s}\n", .{res.json_path}); }
